import{_ as a,a0 as n,w as r,s as p,I as s,x as i,a1 as d,A as l,ao as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"4 個用來擦除數據的 Linux 工具 | LCTT x X-CMD","titleTemplate":false,"description":"4 個用來擦除數據的 Linux 工具 | LCTT (202110) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"4 個用來擦除數據的 Linux 工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"4 個用來擦除數據的 Linux 工具 | LCTT (202110) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202110/20211018 4 Linux tools to erase your data","title":"4 個用來擦除數據的 Linux 工具","tag":"202110","desc":""},"relativePath":"202110/20211018 4 Linux tools to erase your data.md","filePath":"[post].md"}'),u={name:"202110/20211018 4 Linux tools to erase your data.md"};function h(g,e,k,f,m,b){const t=n("Link");return r(),p("div",null,[e[28]||(e[28]=s("h1",{id:"_4-個用來擦除數據的-linux-工具",tabindex:"-1"},[i("4 個用來擦除數據的 Linux 工具 "),s("a",{class:"header-anchor",href:"#_4-個用來擦除數據的-linux-工具","aria-label":"Permalink to “4 個用來擦除數據的 Linux 工具”"},"​")],-1)),e[29]||(e[29]=s("blockquote",null,[s("p",null,"用這些開源工具從你的硬盤驅動器中擦除數據。")],-1)),e[30]||(e[30]=s("p",null,[s("img",{src:"https://img.linux.net.cn/data/attachment/album/202110/23/113918sdojp6sj0odgis16.jpg",alt:""})],-1)),s("p",null,[e[2]||(e[2]=i("保持數據安全的最好方法之一是隻向加密的硬盤驅動器寫入數據。在一個標準的硬盤上，只要把硬盤掛載就可以查看數據，就像 U 盤一樣，甚至可以用 ",-1)),d(t,{href:"https://www.redhat.com/sysadmin/find-lost-files-scalpel"},{default:l(()=>[...e[0]||(e[0]=[i("Scalpel",-1)])]),_:1}),e[3]||(e[3]=i(" 和 ",-1)),d(t,{href:"https://www.redhat.com/sysadmin/recover-partition-files-testdisk"},{default:l(()=>[...e[1]||(e[1]=[i("Testdisk",-1)])]),_:1}),e[4]||(e[4]=i(" 等工具顯示和恢復已刪除的數據。但是在一個加密的驅動器上，如果沒有解密密鑰（通常是你在掛載驅動器時輸入的密碼），數據是無法被讀取的。",-1))]),e[31]||(e[31]=o('<p>加密可以在你安裝操作系統時建立，有些操作系統甚至可以在安裝後的任何時候激活加密功能。</p><p>但是，當你賣掉一台電腦或更換一個一開始就沒有被加密的驅動器時，你該怎麼辦呢？</p><p>與從一開始就加密你的數據相比，最好的辦法是在你用完硬盤後刪除數據。</p><h3 id="負責任的看管者" tabindex="-1">負責任的看管者 <a class="header-anchor" href="#負責任的看管者" aria-label="Permalink to “負責任的看管者”">​</a></h3><p>我經常被要求幫助客户升級一台舊電腦。無一例外，他們更願意幫助我回收它們，使它們能被別人使用。我很樂意翻新這些舊電腦，用較新的固態驅動器來改裝它們，極大地提高性能。</p><p>然而，把一箇舊驅動器扔進垃圾桶並不是一個好主意。它需要被擦除，然後被妥善處理。我沒有把硬盤留在原來的電腦裏，而是把它們取出來，放在一個硬盤盒裏，然後把它們連接到我的 Linux 電腦上。有幾個 Linux 工具可以很容易地完成這個任務。其中一個是 <strong>Gnu Shred</strong>。</p><h3 id="gnu-shred" tabindex="-1">GNU Shred <a class="header-anchor" href="#gnu-shred" aria-label="Permalink to “GNU Shred”">​</a></h3><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo shred -vfz /dev/sdX</span></span></code></pre></div><p>Shred 有許多選項：</p><ul><li><code>-n</code> - 覆蓋的次數。默認是三次。</li><li><code>-u</code> - 覆蓋並刪除。</li><li><code>-s</code> - 要粉碎的字節數。</li><li><code>-v</code> - 顯示擴展信息。</li><li><code>-f</code> - 必要時強制改變權限以允許寫入。</li><li><code>-z</code> - 最後用 0 覆蓋來隱藏粉碎。</li></ul><p>使用 <code>shred --help</code> 獲取更多信息</p><h3 id="shredos" tabindex="-1">ShredOS <a class="header-anchor" href="#shredos" aria-label="Permalink to “ShredOS”">​</a></h3><p>ShredOS 是一個<ruby>即用<rt>Live</rt></ruby> Linux 發行版，它的唯一目的是清除驅動器的全部內容。它是在一個名為 DBAN 的類似發行版停止維護後開發的。它使用 <code>nwipe</code> 應用，它是 DBAN 的 <code>dwipe</code> 的一個分叉。你可以通過下載 32 位或 64 位鏡像，並在 Linux 和 macOS 上使用 <code>dd</code> 命令將其寫入驅動器來製作一個可啓動的 USB 驅動器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dd if=shredos.img of=/dev/sdX bs=4M status=progress</span></span></code></pre></div>',14)),s("p",null,[e[6]||(e[6]=i("另外，你可以在 Linux、macOS 和 Windows 上使用 ",-1)),d(t,{href:"https://opensource.com/article/18/7/getting-started-etcherio"},{default:l(()=>[...e[5]||(e[5]=[i("Etcher",-1)])]),_:1}),e[7]||(e[7]=i(" 工具燒錄。",-1))]),e[32]||(e[32]=o('<h3 id="dd-命令" tabindex="-1">dd 命令 <a class="header-anchor" href="#dd-命令" aria-label="Permalink to “dd 命令”">​</a></h3><p>清除驅動器的一個常見方法是使用 Linux 的 <code>dd</code> 命令。幾乎所有的 Linux 安裝都安裝了 <code>dd</code> 工具。確保該驅動器沒有被掛載。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo umount /dev/sdXY -l</span></span></code></pre></div><p>如果你想在整個目標磁盤上寫零，執行以下命令。這可能需要一個整個通宵。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dd if=/dev/urandom of=/dev/sdX bs=10M</span></span></code></pre></div><p><strong>警告</strong>：請確保你知道你在系統中的位置，並以正確的驅動器為目標，這樣你就不會意外地刪除自己的數據。</p><h3 id="nvme-cli" tabindex="-1">Nvme-cli <a class="header-anchor" href="#nvme-cli" aria-label="Permalink to “Nvme-cli”">​</a></h3>',7)),s("p",null,[e[9]||(e[9]=i("如果你的計算機包含一個較新的 NVMe 驅動器，你可以安裝 ",-1)),d(t,{href:"https://opensource.com/article/21/9/nvme-cli"},{default:l(()=>[...e[8]||(e[8]=[i("nvme-cli",-1)])]),_:1}),e[10]||(e[10]=i(" 程序，並使用 ",-1)),e[11]||(e[11]=s("code",null,"sanitize",-1)),e[12]||(e[12]=i(" 選項來清除你的驅動器。",-1))]),e[33]||(e[33]=o('<p><code>nvme sanitize help</code> 命令提供了選項列表：</p><ul><li><code>--no-dealloc</code>、<code>-d</code> - 淨化後不解除分配。</li><li><code>--oipbp</code>、<code>-i</code> - 每次覆寫後反轉模式。</li><li><code>--owpass=</code>、<code>-n</code> - 覆寫次數。</li><li><code>--ause</code>、<code>-u</code> - 允許無限制淨化退出。</li><li><code>--sanact=</code>、<code>-a</code> - 淨化動作。</li><li><code>--ovrpat=</code>、<code>-p</code> - 覆寫模式。</li></ul><p>下面是我使用的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo nvme sanitize /dev/nvme0nX</span></span></code></pre></div><p>這裏的警告與格式化過程相同：首先備份重要的數據，因為這個命令會擦除這些數據！</p><h3 id="信息管理" tabindex="-1">信息管理 <a class="header-anchor" href="#信息管理" aria-label="Permalink to “信息管理”">​</a></h3><p>你保存在計算機上的信息是很重要的。它屬於你，也屬於其他任何人。當你賣掉一台電腦或處理一個硬盤時，確保你已經用這些很棒的工具之一清除了你的數據。</p><hr>',8)),s("p",null,[e[14]||(e[14]=i("via: ",-1)),d(t,{href:"https://opensource.com/article/21/10/linux-tools-erase-data"},{default:l(()=>[...e[13]||(e[13]=[i("https://opensource.com/article/21/10/linux-tools-erase-data",-1)])]),_:1})]),s("p",null,[e[19]||(e[19]=i("作者：",-1)),d(t,{href:"https://opensource.com/users/don-watkins"},{default:l(()=>[...e[15]||(e[15]=[i("Don Watkins",-1)])]),_:1}),e[20]||(e[20]=i(" 選題：",-1)),d(t,{href:"https://github.com/lujun9972"},{default:l(()=>[...e[16]||(e[16]=[i("lujun9972",-1)])]),_:1}),e[21]||(e[21]=i(" 譯者：",-1)),d(t,{href:"https://github.com/geekpi"},{default:l(()=>[...e[17]||(e[17]=[i("geekpi",-1)])]),_:1}),e[22]||(e[22]=i(" 校對：",-1)),d(t,{href:"https://github.com/wxy"},{default:l(()=>[...e[18]||(e[18]=[i("wxy",-1)])]),_:1})]),s("p",null,[e[25]||(e[25]=i("本文由 ",-1)),d(t,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...e[23]||(e[23]=[i("LCTT",-1)])]),_:1}),e[26]||(e[26]=i(" 原創編譯，",-1)),d(t,{href:"https://linux.cn/"},{default:l(()=>[...e[24]||(e[24]=[i("Linux中國",-1)])]),_:1}),e[27]||(e[27]=i(" 榮譽推出",-1))])])}const v=a(u,[["render",h]]);export{T as __pageData,v as default};
